@import 'c/rlySharedStyles';

.rr-pa { background: #fff; border: 1px solid #e5e5e5; border-radius: 4px; box-shadow: 0 2px 2px rgba(0, 0, 0, 0.05); padding: 12px 14px 14px; display: flex; flex-direction: column; gap: 10px; margin-bottom: 12px; }
.rr-pa-head { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.rr-pa-row { display: flex; align-items: flex-start; gap: 16px; flex-wrap: wrap; }
.rr-grow { flex: 1 1 260px; min-width: 0; }
.rr-weak { color: #5c5c5c; }
.rr-small { font-size: 12px; margin: 0; }
.rr-msg-wait { background: #fef1cd; color: #7a4a02; }
.rr-pill { display: inline-block; font-size: 11px; font-weight: 700; padding: 2px 9px; border-radius: 10px; white-space: nowrap; }
.rr-pill-none { background: #f3f3f3; color: #5c5c5c; }
